	if err != nil {
		return err
	}
	if !pathInside(rootResolved, pathResolved) {
		return fmt.Errorf("path escapes root through symlinks: %s", rel)
	}
	return nil
}

func rejectExistingSymlinkPathComponents(root, rel string) error {
