}

func writeBrainManifestAndReadme(outputDir string, manifest exportManifest) error {
	normalizeBrainManifest(&manifest)
	manifest.SchemaVersion = brainManifestSchemaVersion
	data, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return fmt.Errorf("encode %s: %w", exportManifestFileName, err)
	}
	data = append(data, '\n')
	if err := writeFileAtomic(filepath.Join(outputDir, exportManifestFileName), data, 0o600); err != nil {
		return fmt.Errorf("write %s: %w", exportManifestFileName, err)
	}
	if err := writeFileAtomic(filepath.Join(outputDir, exportReadmeFileName), []byte(renderBrainReadme(manifest)), 0o600); err != nil {
		return fmt.Errorf("write brain readme: %w", err)
	}
	return nil
}

func writeFileAtomic(path string, data []byte, perm os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tmpName)
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Chmod(perm); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmpName, path); err != nil {
		return err
	}
	cleanup = false
	return nil
}

func renderBrainReadme(manifest exportManifest) string {
	if manifest.Sources == nil || (manifest.Sources.Seed == nil && manifest.Sources.Semantic == nil) {
		return renderExportReadme(manifest)
	}
	return renderCombinedBrainReadme(manifest)
}

