+func mcpString(args map[string]any, key string) string {
+	if value, ok := args[key].(string); ok {
+		return value
+	}
+	return ""
+}
+
+func mcpInt(args map[string]any, key string, fallback int) int {
+	value, ok := args[key]
+	if !ok {
+		return fallback
+	}
+	switch typed := value.(type) {
+	case float64:
+		if typed > 0 {
+			return int(typed)
+		}
+	case int:
+		if typed > 0 {
+			return typed
+		}
+	}
+	return fallback
+}
+
+func readMCPMessage(reader *bufio.Reader) (mcpMessage, error) {
+	length := -1
+	for {
+		line, err := reader.ReadString('\n')
+		if err != nil {
+			return mcpMessage{}, err
+		}
+		line = strings.TrimRight(line, "\r\n")
+		if line == "" {
+			break
+		}
+		name, value, ok := strings.Cut(line, ":")
+		if ok && strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
+			parsed, err := strconv.Atoi(strings.TrimSpace(value))
+			if err != nil {
+				return mcpMessage{}, err
+			}
+			length = parsed
+		}
+	}
+	if length < 0 {
+		return mcpMessage{}, errors.New("missing Content-Length")
+	}
+	data := make([]byte, length)
+	if _, err := io.ReadFull(reader, data); err != nil {
+		return mcpMessage{}, err
+	}
+	var msg mcpMessage
+	if err := json.Unmarshal(data, &msg); err != nil {
+		return mcpMessage{}, err
+	}
+	return msg, nil
+}
+
+func writeMCPMessage(out io.Writer, msg mcpMessage) error {
+	data, err := json.Marshal(msg)
+	if err != nil {
+		return err
+	}
+	_, err = fmt.Fprintf(out, "Content-Length: %d\r\n\r\n%s", len(data), data)
+	return err
+}

